EXTRA = [
 ("TEN21", "ENTITY", 2, "The landlord must not keep flammable or dangerous materials in the premises, except household cooking gas cylinders.", "मकान मालिक घरेलू रसोई गैस सिलेंडर के अलावा परिसर में कोई ज्वलनशील या खतरनाक सामान नहीं रखेगा।"),
 ("TEN21", "HALLUC", 4, "The tenant must not keep flammable or dangerous materials in the premises, except household cooking gas cylinders, and must keep a fire extinguisher in the premises.", "किरायेदार घरेलू रसोई गैस सिलेंडर के अलावा परिसर में कोई ज्वलनशील या खतरनाक सामान नहीं रखेगा, और परिसर में एक अग्निशामक यंत्र रखेगा।"),
 ("TEN22", "NUMBER", 3, "The landlord will give the tenant one covered car parking space for the tenant's use only.", "मकान मालिक किरायेदार को केवल उसके उपयोग के लिए एक ढकी हुई कार पार्किंग जगह देगा।"),
 ("TEN22", "MODALITY", 2, "The landlord may give the tenant two covered car parking spaces for the tenant's use only.", "मकान मालिक किरायेदार को केवल उसके उपयोग के लिए दो ढकी हुई कार पार्किंग जगहें दे सकता है।"),
 ("TEN23", "DATE", 3, "In the last three months of the tenancy, the tenant must allow the landlord to show the premises to possible new tenants.", "किरायेदारी के आखिरी तीन महीनों में किरायेदार को मकान मालिक को संभावित नए किरायेदारों को परिसर दिखाने देना होगा।"),
 ("TEN23", "HALLUC", 4, "In the last month of the tenancy, the tenant must allow the landlord to show the premises to possible new tenants, but only on weekends.", "किरायेदारी के आखिरी महीने में किरायेदार को मकान मालिक को संभावित नए किरायेदारों को परिसर दिखाने देना होगा, लेकिन केवल सप्ताहांत पर।"),
 ("TEN24", "EXC_REMOVED", 2, "The rent cannot be changed during the tenancy.", "किरायेदारी के दौरान किराया नहीं बदला जा सकता।"),
 ("TEN24", "DATE", 3, "The rent cannot be changed during the first year of the tenancy, except as this agreement allows.", "किरायेदारी के पहले साल के दौरान किराया नहीं बदला जा सकता, सिवाय उसके जो यह अनुबंध अनुमति देता है।"),
 ("TEN25", "ENTITY", 1, "The landlord must pay for damage to the premises caused by the tenant's carelessness, but not for normal wear and tear.", "किरायेदार की लापरवाही से परिसर को हुए नुकसान की भरपाई मकान मालिक करेगा, लेकिन सामान्य टूट-फूट की नहीं।"),
 ("TEN25", "OMIT_COND", 3, "The tenant must pay for damage to the premises, but not for normal wear and tear.", "परिसर को हुए नुकसान की भरपाई किरायेदार करेगा, लेकिन सामान्य टूट-फूट की नहीं।"),
 ("TEN26", "SCOPE", 4, "The landlord must give the tenant a signed receipt for every cash rent payment received.", "मकान मालिक को किराये के हर नकद भुगतान की हस्ताक्षरित रसीद किरायेदार को देनी होगी।"),
 ("TEN26", "MINOR", 6, "The landlord must give the tenant a receipt for every rent payment received.", "मकान मालिक को किराये के हर भुगतान की रसीद किरायेदार को देनी होगी।"),
 ("TEN27", "HALLUC", 3, "The furniture and fittings in Schedule A come with the premises and must be returned in the same condition, allowing for normal wear and tear, and the tenant must pay a monthly hire charge for them.", "अनुसूची क का फ़र्नीचर और सामान परिसर के साथ मिलता है और सामान्य टूट-फूट को छोड़कर उसी हालत में लौटाना होगा, और किरायेदार को इनके लिए हर महीने किराया-शुल्क देना होगा।"),
 ("TEN27", "SCOPE", 4, "The furniture in Schedule A comes with the premises and must be returned in the same condition, allowing for normal wear and tear.", "अनुसूची क का फ़र्नीचर परिसर के साथ मिलता है और सामान्य टूट-फूट को छोड़कर उसी हालत में लौटाना होगा।"),
 ("TEN28", "EXC_REMOVED", 3, "During the tenancy, the tenant cannot be evicted.", "किरायेदारी के दौरान किरायेदार को बेदखल नहीं किया जा सकता।"),
 ("TEN28", "MODALITY", 2, "During the tenancy, the tenant can be evicted, preferably by following the procedure set by law.", "किरायेदारी के दौरान किरायेदार को बेदखल किया जा सकता है, और बेहतर होगा कि इसके लिए कानून द्वारा तय प्रक्रिया अपनाई जाए।"),
 ("TEN29", "NUMBER", 2, "The landlord pays the society maintenance charge of Rs. 30,000 a month.", "सोसाइटी का 30,000 रुपये महीने का रखरखाव शुल्क मकान मालिक भरेगा।"),
 ("TEN29", "DATE", 3, "The landlord pays the society maintenance charge of Rs. 3,000 a year.", "सोसाइटी का 3,000 रुपये साल का रखरखाव शुल्क मकान मालिक भरेगा।"),
 ("TEN30", "NUMBER", 3, "The tenant can end the agreement during the six-month lock-in period only if the tenant pays half the rent for the rest of the lock-in period.", "छह महीने की लॉक-इन अवधि के दौरान किरायेदार अनुबंध तभी खत्म कर सकता है जब वह बची हुई लॉक-इन अवधि का आधा किराया दे।"),
 ("TEN30", "OMIT_COND", 2, "The tenant can end the agreement during the six-month lock-in period.", "छह महीने की लॉक-इन अवधि के दौरान किरायेदार अनुबंध खत्म कर सकता है।"),
 ("TEN31", "DATE", 3, "The landlord must get the premises whitewashed and painted once every five years.", "मकान मालिक को हर पाँच साल में एक बार परिसर की सफ़ेदी और पेंटिंग करानी होगी।"),
 ("TEN31", "ENTITY", 2, "The tenant must get the premises whitewashed and painted once every three years.", "किरायेदार को हर तीन साल में एक बार परिसर की सफ़ेदी और पेंटिंग करानी होगी।"),
 ("TEN32", "NEGATION", 2, "The tenant does not have to follow housing society rules, but must not disturb other residents.", "किरायेदार को सोसाइटी के नियम मानना ज़रूरी नहीं है, लेकिन दूसरे निवासियों को परेशान नहीं करना होगा।"),
 ("TEN32", "MINOR", 6, "The tenant must follow housing society rules and must not disturb other residents.", "किरायेदार को सोसाइटी के नियम मानने होंगे और दूसरे निवासियों को परेशान नहीं करना होगा।"),
 ("TEN33", "SCOPE", 4, "If fire or flood makes the premises unlivable, no rent is payable until the premises are repaired.", "यदि आग या बाढ़ से परिसर रहने लायक न रहे, तो मरम्मत होने तक कोई किराया नहीं देना होगा।"),
 ("TEN33", "NEGATION", 1, "If fire, flood or earthquake makes the premises unlivable, rent is still payable until the premises are repaired.", "यदि आग, बाढ़ या भूकंप से परिसर रहने लायक न रहे, तो भी मरम्मत होने तक किराया देना होगा।"),
 ("TEN34", "NUMBER", 2, "The tenant must not pay more than Rs. 1,000 in cash for rent in a single payment.", "किरायेदार एक बार में 1,000 रुपये से ज़्यादा किराया नकद नहीं देगा।"),
 ("TEN34", "MODALITY", 3, "The tenant should preferably not pay more than Rs. 10,000 in cash for rent in a single payment.", "किरायेदार के लिए बेहतर है कि वह एक बार में 10,000 रुपये से ज़्यादा किराया नकद न दे।"),
 ("TEN35", "NEGATION", 2, "Before asking for rent higher than the agreed rate, the landlord does not have to give the tenant three months' notice.", "सहमत दर से ज़्यादा किराया माँगने से पहले मकान मालिक को किरायेदार को तीन महीने का नोटिस देना ज़रूरी नहीं है।"),
 ("TEN35", "MINOR", 6, "Before asking for higher rent, the landlord must give the tenant three months' notice.", "ज़्यादा किराया माँगने से पहले मकान मालिक को किरायेदार को तीन महीने का नोटिस देना होगा।"),
 ("TEN36", "EXC_REMOVED", 3, "Only the tenant may live in the premises, unless the landlord agrees to others.", "परिसर में केवल किरायेदार रह सकता है, जब तक मकान मालिक दूसरों के लिए सहमति न दे।"),
 ("TEN36", "ENTITY", 2, "Only the tenant's immediate family may live in the premises, unless the housing society agrees to others.", "परिसर में केवल किरायेदार का निकटतम परिवार रह सकता है, जब तक सोसाइटी दूसरों के लिए सहमति न दे।"),
 ("TEN37", "ENTITY", 2, "The landlord cannot object to the tenant installing an air-conditioner, as long as the landlord pays for the installation.", "किरायेदार एयर-कंडीशनर लगाए तो मकान मालिक आपत्ति नहीं कर सकता, बशर्ते लगाने का खर्च मकान मालिक दे।"),
 ("TEN37", "HALLUC", 4, "The landlord cannot object to the tenant installing an air-conditioner, as long as the tenant pays for the installation and removes it when the tenancy ends.", "किरायेदार एयर-कंडीशनर लगाए तो मकान मालिक आपत्ति नहीं कर सकता, बशर्ते लगाने का खर्च किरायेदार दे और किरायेदारी खत्म होने पर उसे हटा दे।"),
 ("TEN38", "MODALITY", 1, "The tenant may put up a signboard or advertisement outside the building.", "किरायेदार इमारत के बाहर साइनबोर्ड या विज्ञापन लगा सकता है।"),
 ("TEN38", "SCOPE", 4, "The tenant must not put up any signboard or advertisement on the front of the building.", "किरायेदार इमारत के सामने वाले हिस्से पर कोई साइनबोर्ड या विज्ञापन नहीं लगाएगा।"),
 ("TEN39", "NEGATION", 1, "The tenant must not pay the rent directly into the landlord's bank account listed in Schedule B.", "किरायेदार किराया सीधे अनुसूची ख में दिए गए मकान मालिक के बैंक खाते में जमा नहीं करेगा।"),
 ("TEN39", "MINOR", 6, "The tenant must pay the rent directly into the landlord's bank account.", "किरायेदार को किराया सीधे मकान मालिक के बैंक खाते में जमा करना होगा।"),
 ("TEN40", "NUMBER", 3, "The agreement can be renewed for two more terms if both parties agree and sign a new written agreement.", "दोनों पक्ष सहमत हों और नया लिखित अनुबंध करें, तो अनुबंध अगली दो अवधियों के लिए बढ़ाया जा सकता है।"),
 ("TEN40", "OMIT_COND", 3, "The agreement can be renewed for another term if both parties agree.", "दोनों पक्ष सहमत हों, तो अनुबंध अगली अवधि के लिए बढ़ाया जा सकता है।"),
]
